# Let me verify by tracing through the BFS levels manually
def bfs_debug(graph, start, target_depth):
    """Debug version showing each level"""
    from collections import deque

    visited = {start}
    queue = deque([(start, 0)])
    level_nodes = {0: [start]}

    while queue:
        node, depth = queue.popleft()

        if depth >= target_depth:
            break

        next_depth = depth + 1
        if next_depth not in level_nodes:
            level_nodes[next_depth] = []

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, next_depth))
                level_nodes[next_depth].append(neighbor)

    for d in sorted(level_nodes.keys()):
        print(f"Depth {d}: {level_nodes[d]}")

    return level_nodes.get(target_depth, [])

result = bfs_debug(actual_graph, start_node, 4)
print(f"\nNodes at exactly depth 4: {result}")
